function validateCommand(command, policy = DEFAULT_AUTONOMOUS_POLICY) {
  const normalized = command.trim();
  if (!normalized) {
    return {
      allowed: false,
      reason: "Command cannot be empty."
    };
  }
  for (const [pattern, reason] of BLOCKED_PATTERNS) {
    if (pattern.test(normalized)) {
      return {
        allowed: false,
        reason: `Command blocked: ${reason}.`
      };
    }
  }
  if (!policy.allowShell) {
    return {
      allowed: false,
      reason: "Shell execution is disabled."
    };
  }
  if (!policy.allowGit && /\bgit\b/i.test(normalized)) {
    return {
      allowed: false,
      reason: "Git access is disabled."
    };
  }
  if (!policy.allowDeployment && /\b(deploy|production|release|cloud\s*run|vercel)\b/i.test(
    normalized
  )) {
    return {
      allowed: false,
      reason: "Production deployment is disabled."
    };
  }
  if (!policy.allowNetwork && /\b(curl|wget|nc|netcat|ssh|scp|ftp)\b/i.test(normalized)) {
    return {
      allowed: false,
      reason: "Network-capable shell utilities are disabled."
    };
  }
  return {
    allowed: true
  };
}
