          task: null,
          lastHeartbeat: Date.now(),
          tasksCompleted: 0,
          signature: `sec-key-${agent.id}-cust`,
          angle,
          radius: r,
          cx: Math.round(410 + r * Math.cos(rad)),
          cy: Math.round(310 + r * Math.sin(rad)),
