      let score = 0;
      for (const keyword of agent.specialties) {
        if (text.includes(keyword.toLowerCase())) {
          score += 3;
        }
      }
      if (text.includes(agent.role.toLowerCase().slice(0, 5))) {
        score += 2;
      }
      if (score > highestScore) {
        highestScore = score;
        bestAgent = agent;
      }
