      A4: 4,
      // SafetyGuard
      A5: 5,
      // InfraStaging
      A6: 6,
      // OutcomeEval
      A7: 7,
      // NegotiationEngineer
      A8: 8,
      // CurriculumMgr
      "ENG-9": 9,
      // MasterMetaAgent
      "ENG-10": 10
