// risk-engine/risk.calculator.ts
var RiskCalculator = class {
  static calculate(tool, action, parameters, environment = "development") {
    const rule = riskRules.find(
      (r) => r.tool === tool && r.action === action
    );
    if (!rule) {
      return {
        riskLevel: "HIGH",
        approvalRequired: true,
        reason: `Defaulting to SECURE-HIGH risk: No explicit risk rule registered for ${tool}.${action}`
      };
    }
    let riskLevel = rule.baseRisk;
    let approvalRequired = rule.triggersApproval;
    const reasons = [`Base rule: ${tool}.${action} maps to ${riskLevel}`];
    if (environment === "production") {
      if (riskLevel === "LOW") {
        riskLevel = "MEDIUM";
        reasons.push("Risk promoted to MEDIUM due to Production workspace boundaries");
      } else if (riskLevel === "MEDIUM") {
        riskLevel = "HIGH";
        approvalRequired = true;
        reasons.push("Risk promoted to HIGH with forced Approval due to Production environment");
      } else if (riskLevel === "HIGH") {
        riskLevel = "CRITICAL";
        approvalRequired = true;
        reasons.push("Risk promoted to CRITICAL due to Production environment constraints");
      }
    }
    if (rule.destructive) {
      riskLevel = "CRITICAL";
      approvalRequired = true;
      reasons.push("Destructive operation detected: forces CRITICAL risk and human-in-the-loop approval");
    }
    if (rule.spendingLimitDollars && parameters.amount) {
      const amount = parseFloat(parameters.amount);
      if (!isNaN(amount) && amount > rule.spendingLimitDollars) {
        riskLevel = "CRITICAL";
        approvalRequired = true;
        reasons.push(`Spending threshold violated: Requested $${amount} exceeds limit of $${rule.spendingLimitDollars}`);
      }
    }
    if (riskLevel === "CRITICAL") {
      approvalRequired = true;
    }
    return {
      riskLevel,
      approvalRequired,
      reason: reasons.join(". ")
    };
  }
};

// apps/control-plane/integrations/gateway/policy.middleware.ts
var PolicyEngine = class {
  static {
    this.policies = [
      {
        id: "pol-git-merge",
        tool: "github",
        action: "merge_pull_request",
        allowed: true,
        requiresApproval: true,
        allowedDepartments: ["Engineering", "Executive"]
      },
      {
        id: "pol-db-write-prod",
        tool: "postgresql",
        action: "update",
        environment: "production",
        allowed: false,
        requiresApproval: true
      },
      {
        id: "pol-db-alter",
        tool: "postgresql",
        action: "alter_schema",
        allowed: true,
        requiresApproval: true,
        allowedDepartments: ["Engineering"]
      },
      {
        id: "pol-delete-bucket",
        tool: "cloud_storage",
        action: "delete",
        allowed: true,
        requiresApproval: true,
        blockedRoles: ["assistant", "intern"]
      },
      {
        id: "pol-invoice-finance",
        tool: "stripe",
        action: "create_invoice",
        allowed: true,
        requiresApproval: true,
        maxSpendingLimit: 2e3,
        allowedDepartments: ["Finance", "Executive"]
      }
    ];
  }
  static evaluate(context) {
    const matchedRule = this.policies.find(
      (p) => p.tool === context.tool && p.action === context.action && (!p.environment || p.environment === context.environment)
    );
    if (!matchedRule) {
      return { allowed: true, reason: "No restrictive policy rule found. Proceeding to standard risk evaluation.", requiresApproval: false };
    }
    if (!matchedRule.allowed) {
      return {
        allowed: false,
        reason: `Access Denied: Enterprise policy [${matchedRule.id}] explicitly forbids ${context.tool}.${context.action} operations in ${context.environment} environments.`,
        requiresApproval: false
      };
    }
    if (matchedRule.allowedDepartments && !matchedRule.allowedDepartments.includes(context.department)) {
      return {
        allowed: false,
        reason: `Department Boundary Violation: Operational action "${context.tool}.${context.action}" is restricted to departments: ${matchedRule.allowedDepartments.join(", ")}. Employee belongs to: ${context.department}`,
        requiresApproval: false
      };
    }
    if (matchedRule.blockedRoles && matchedRule.blockedRoles.includes(context.role.toLowerCase())) {
      return {
        allowed: false,
        reason: `Role Security Restriction: Your role [${context.role}] is explicitly prohibited from triggering action "${context.tool}.${context.action}" under policy guidelines.`,
        requiresApproval: false
      };
    }
    if (matchedRule.maxSpendingLimit && context.parameters.amount) {
      const spending = parseFloat(context.parameters.amount);
      if (!isNaN(spending) && spending > matchedRule.maxSpendingLimit) {
        return {
          allowed: false,
          reason: `Financial Cap Exceeded: Policy limits ${context.tool}.${context.action} to $${matchedRule.maxSpendingLimit}. Requested amount: $${spending}`,
          requiresApproval: false
        };
      }
    }
    return {
      allowed: true,
      reason: `Policy check passed under criteria [${matchedRule.id}].`,
      requiresApproval: matchedRule.requiresApproval
    };
  }
};

