function isSoftwareEngineerAgent(employee) {
  if (!employee) return false;
  const engAgentIds = [
    "cline",
    "ruflo-coder",
    "ruflo_coder",
    "ruflo",
    "aria",
    "sub-eng-arch",
    "sub-eng-backend",
    "eng_frontend",
    "eng_mobile",
    "eng_devops",
    "eng_qa",
    "pete-miller",
    "cline_labs",
    "eng_coder"
  ];
  if (engAgentIds.includes((employee.id || "").toLowerCase())) return true;
  const deptIdLower = (employee.departmentId || "").toLowerCase();
  const deptNameLower = (employee.department || "").toLowerCase();
  const engDepts = ["engineering", "eng_labs", "cloud_ops", "datacenter", "infrastructure", "rnd"];
  if (engDepts.includes(deptIdLower)) return true;
  if (deptNameLower.includes("engineering") || deptNameLower.includes("software") || deptNameLower.includes("data center") || deptNameLower.includes("cloud infrastructure")) {
    return true;
  }
  const roleTitleStr = `${employee.role || ""} ${employee.title || ""} ${employee.name || ""}`.toLowerCase();
  const engKeywords = [
    "software engineer",
    "systems architect",
    "full-stack",
    "backend",
    "frontend",
    "devops",
    "coder",
    "developer",
    "software",
    "compiler",
    "lab master",
    "code master",
    "cto"
  ];
  return engKeywords.some((kw) => roleTitleStr.includes(kw));
}
